#!/usr/bin/env node
// Generate offset-accessor views over guest memory from layouts/<...>/<Class>.json.
//
// Each layout file: { name, base, size, vptr, fields: [{ offset, size, type, name }] }
// Output: src/game/layouts.rs  (do not edit by hand)
//
// A view is a 32-bit guest pointer plus big-endian accessors. Nothing is copied
// or reinterpreted; every getter/setter calls the platform's byte-ordered
// read/write helpers on `self.addr + offset`.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const ROOT = path.resolve(__dirname, '..');
const LAYOUT_DIR = path.join(ROOT, 'layouts');
const OUT = path.join(ROOT, 'src', 'game', 'layouts.rs');

function walk(dir) {
  const out = [];
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) out.push(...walk(p));
    else if (e.name.endsWith('.json')) out.push(p);
  }
  return out;
}

const snake = (s) =>
  s.replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1_$2')
    .toLowerCase();

const camel = (s) =>
  s.split(/[^A-Za-z0-9]+/).filter(Boolean)
    .map((w) => w[0].toUpperCase() + w.slice(1)).join('');

function structIdent(name) {
  const parts = name.split('_');
  if (parts.length > 1 && parts[parts.length - 1] === 'c') parts.pop();
  return camel(parts.join('_'));
}

function fieldIdent(name) {
  let base = name;
  if (/^mp[A-Z]/.test(name)) base = 'p' + name.slice(2);
  else if (/^m[_A-Z]/.test(name)) base = name.slice(1);
  let s = snake(base);
  if (/^[0-9]/.test(s)) s = 'field_' + s;
  return s;
}

const PRIM = {
  u8: ['u8', 'read_u8', 'write_u8', 'u8'],
  s8: ['i8', 'read_u8', 'write_u8', 'i8'],
  i8: ['i8', 'read_u8', 'write_u8', 'i8'],
  bool: ['bool', 'read_u8', 'write_u8', 'bool'],
  u16: ['u16', 'read_u16', 'write_u16', 'u16'],
  s16: ['i16', 'read_u16', 'write_u16', 'i16'],
  i16: ['i16', 'read_u16', 'write_u16', 'i16'],
  u32: ['u32', 'read_u32', 'write_u32', 'u32'],
  i32: ['i32', 'read_i32', 'write_i32', 'i32'],
  f32: ['f32', 'read_f32', 'write_f32', 'f32'],
};

const VEC = {
  mVec3_c: { ty: 'Vec3', kind: 'vec3' },
  mVec2_c: { ty: 'Vec2', kind: 'vec2' },
  mAng3_c: { ty: 'Ang3', kind: 'ang3' },
};

const files = walk(LAYOUT_DIR).sort();
const classes = files.map((f) => JSON.parse(fs.readFileSync(f, 'utf8')));
const byName = new Map(classes.map((c) => [c.name, c]));

let src = '';
src += '//! Offset-accessor views over guest memory. GENERATED by\n';
src += '//! `tools/gen-layout-views.mjs` from `layouts/**/*.json`; do not edit by hand.\n';
src += '//!\n';
src += '//! Each view is a 32-bit guest address plus big-endian accessors. The object\n';
src += '//! stays in guest RAM; nothing is copied or reinterpreted.\n\n';
src += 'use crate::platform;\n\n';

// shared vector views
src += '#[derive(Clone, Copy)]\npub struct Vec3 { pub addr: u32 }\n';
src += 'impl Vec3 {\n';
for (const [i, c] of ['x', 'y', 'z'].entries()) {
  src += `    #[inline] pub unsafe fn ${c}(&self) -> f32 { platform::read_f32(self.addr as usize + ${i * 4}) }\n`;
  src += `    #[inline] pub unsafe fn set_${c}(&self, v: f32) { platform::write_f32(self.addr as usize + ${i * 4}, v) }\n`;
}
src += '}\n\n';
src += '#[derive(Clone, Copy)]\npub struct Vec2 { pub addr: u32 }\n';
src += 'impl Vec2 {\n';
for (const [i, c] of ['x', 'y'].entries()) {
  src += `    #[inline] pub unsafe fn ${c}(&self) -> f32 { platform::read_f32(self.addr as usize + ${i * 4}) }\n`;
  src += `    #[inline] pub unsafe fn set_${c}(&self, v: f32) { platform::write_f32(self.addr as usize + ${i * 4}, v) }\n`;
}
src += '}\n\n';
src += '#[derive(Clone, Copy)]\npub struct Ang3 { pub addr: u32 }\n';
src += 'impl Ang3 {\n';
for (const [i, c] of ['x', 'y', 'z'].entries()) {
  src += `    #[inline] pub unsafe fn ${c}(&self) -> i16 { platform::read_u16(self.addr as usize + ${i * 2}) as i16 }\n`;
  src += `    #[inline] pub unsafe fn set_${c}(&self, v: i16) { platform::write_u16(self.addr as usize + ${i * 2}, v as u16) }\n`;
}
src += '}\n\n';

for (const c of classes) {
  const s = structIdent(c.name);
  src += `/// \`${c.name}\`${c.base ? ` : \`${c.base}\`` : ''}\n`;
  src += '#[derive(Clone, Copy)]\n';
  src += `pub struct ${s} { pub addr: u32 }\n`;
  src += `impl ${s} {\n`;
  if (c.size != null) src += `    pub const SIZE: usize = 0x${c.size.toString(16)};\n`;
  if (c.vptr != null) src += `    pub const OFFSET_VPTR: usize = 0x${c.vptr.toString(16)};\n`;
  src += '    #[inline] pub fn addr(&self) -> u32 { self.addr }\n';
  if (c.base && byName.has(c.base)) {
    const b = structIdent(c.base);
    src += `    #[inline] pub fn as_${snake(structIdent(c.base))}(&self) -> ${b} { ${b} { addr: self.addr } }\n`;
  }

  for (const f of c.fields) {
    if (f.type === 'pad' || f.type === 'vptr') continue;
    const id = fieldIdent(f.name);
    const off = `0x${f.offset.toString(16)}`;
    src += `    pub const OFFSET_${id.toUpperCase()}: usize = ${off};\n`;

    if (VEC[f.type]) {
      const v = VEC[f.type];
      src += `    #[inline] pub fn ${id}(&self) -> ${v.ty} { ${v.ty} { addr: self.addr + Self::OFFSET_${id.toUpperCase()} as u32 } }\n`;
      continue;
    }
    if (PRIM[f.type]) {
      const [ty, rd, wr, cast] = PRIM[f.type];
      let get;
      if (f.type === 'bool') get = `platform::${rd}(self.addr as usize + Self::OFFSET_${id.toUpperCase()}) != 0`;
      else if (['s8', 'i8', 's16', 'i16'].includes(f.type)) get = `platform::${rd}(self.addr as usize + Self::OFFSET_${id.toUpperCase()}) as ${ty}`;
      else get = `platform::${rd}(self.addr as usize + Self::OFFSET_${id.toUpperCase()})`;
      let set;
      if (f.type === 'bool') set = `platform::${wr}(self.addr as usize + Self::OFFSET_${id.toUpperCase()}, if v { 1 } else { 0 })`;
      else if (['s8', 'i8', 's16', 'i16'].includes(f.type)) set = `platform::${wr}(self.addr as usize + Self::OFFSET_${id.toUpperCase()}, v as u${ty === 'i8' ? 8 : 16})`;
      else set = `platform::${wr}(self.addr as usize + Self::OFFSET_${id.toUpperCase()}, v)`;
      src += `    #[inline] pub unsafe fn ${id}(&self) -> ${ty} { ${get} }\n`;
      src += `    #[inline] pub unsafe fn set_${id}(&self, v: ${ty}) { ${set} }\n`;
      continue;
    }
    if (byName.has(f.type)) {
      const v = structIdent(f.type);
      src += `    #[inline] pub fn ${id}(&self) -> ${v} { ${v} { addr: self.addr + Self::OFFSET_${id.toUpperCase()} as u32 } }\n`;
      continue;
    }
    // Guest pointer or a sub-object whose layout is not defined yet: expose its address.
    const ret = /[*]/.test(f.type) ? 'u32' : 'u32';
    src += `    #[inline] pub fn ${id}${/[*]/.test(f.type) ? '' : '_addr'}(&self) -> ${ret} { self.addr + Self::OFFSET_${id.toUpperCase()} as u32 }\n`;
  }
  src += '}\n\n';
}

// per-class size/offset tests
src += '#[cfg(test)]\nmod tests {\n    use super::*;\n';
for (const c of classes) {
  const s = structIdent(c.name);
  src += `\n    #[test]\n    fn ${snake(c.name)}_layout() {\n`;
  if (c.size != null) src += `        assert_eq!(${s}::SIZE, 0x${c.size.toString(16)});\n`;
  for (const f of c.fields) {
    if (f.type === 'pad' || f.type === 'vptr') continue;
    const id = fieldIdent(f.name);
    src += `        assert_eq!(${s}::OFFSET_${id.toUpperCase()}, 0x${f.offset.toString(16)});\n`;
  }
  src += '    }\n';
}
src += '}\n';

fs.writeFileSync(OUT, src);
console.log(`wrote ${path.relative(ROOT, OUT)} (${classes.length} classes, ${src.length} bytes)`);

